+    // Check if already sorted ascending
+    bool asc = true;
+    for (size_t i = 1; i < n; ++i) {
+        if (a[i] < a[i - 1]) { asc = false; break; }
+    }
+    if (asc) return;
+
+    // Check if already sorted descending (reverse)
+    bool desc = true;
+    for (size_t i = 1; i < n; ++i) {
+        if (a[i] > a[i - 1]) { desc = false; break; }
+    }
+    if (desc) {
+        for (size_t i = 0, j = n - 1; i < j; ++i, --j) {
+            std::swap(a[i], a[j]);
+        }
+        return;
+    }
