+    // LSD radix sort with 4 passes of 8 bits
+    std::vector<uint32_t> buf(n);
+    uint32_t* work = a;
+    uint32_t* output = buf.data();
+    bool work_is_a = true;
+
+    for (int pass = 0; pass < 4; ++pass) {
+        uint32_t histogram[256] = {0};
+
+        // Count histogram of current digit
+        for (size_t i = 0; i < n; ++i) {
+            uint32_t digit = (work[i] >> (pass * 8)) & 0xFF;
+            histogram[digit]++;
+        }
+
+        // Check if we can skip this pass (all elements have same digit)
+        bool skip = false;
+        for (int i = 0; i < 256; ++i) {
+            if (histogram[i] == (uint32_t)n) {
+                skip = true;
+                break;
+            }
+        }
+        if (skip) continue;
+
+        // Compute prefix sums for placement
+        uint32_t prefix[256];
+        prefix[0] = 0;
+        for (int i = 1; i < 256; ++i) {
+            prefix[i] = prefix[i - 1] + histogram[i - 1];
+        }
+
+        // Place elements into output
+        for (size_t i = 0; i < n; ++i) {
+            uint32_t digit = (work[i] >> (pass * 8)) & 0xFF;
+            output[prefix[digit]++] = work[i];
+        }
+
+        // Swap work and output
+        std::swap(work, output);
+        work_is_a = !work_is_a;
+    }
+
+    // If final result is not in the original array, copy it
+    if (!work_is_a) {
+        std::copy(work, work + n, a);
